    const toks = _norm(String(who || '').replace(/[^\p{L}\p{N}.\s]+/gu, ' ')).split(' ').filter(Boolean);
    if (!toks.length || toks.every(t => _said.indexOf(' ' + t + ' ') !== -1)) return null;
    const hits = _staff.filter(p => [p.first].concat(p.keys).some(k => k && _said.indexOf(' ' + k + ' ') !== -1
      && toks.some(t => t === k || (k.length >= 4 && t.length >= 4 && _lev(t, k) <= 1) || (k.indexOf(' ') !== -1 && toks.join(' ').indexOf(k) !== -1))));
    return hits.length === 1 ? hits[0] : null;
  };
  const _suggest = who => {
    const toks = _norm(who).split(' ').filter(t => t.length > 1);
    return _staff.filter(p => toks.some(t => p.first === t || p.keys.indexOf(t) !== -1)).map(p => p.name);
  };
  const _segs = String(REQ.description || '').split('|');
  const _segIdx = re => _segs.findIndex(s => re.test(s.trim()));
  const _eIdx = _segIdx(/^engineer\s*:/i), _aIdx = _segIdx(/^arranger\s*:/i);
  const _engRaw = String(REQ.engineer || '').trim() || (_eIdx !== -1 ? _segs[_eIdx].trim().replace(/^engineer\s*:\s*/i, '') : '');
  const _arrRaw = _aIdx !== -1 ? _segs[_aIdx].trim().replace(/^arranger\s*:\s*/i, '') : '';
  const _checks = [['engineer', _engRaw], ['arranger', _arrRaw]].filter(c => _split(c[1]).who);
  if (_checks.length && !_staff.length) {
    return [{ json: { verdict:'REJECTED', reason:'ENGINEER_UNVERIFIED',
      human:'Nothing was booked - the staff list could not be read, so the engineer could not be checked. Tell the requester it failed and to try again.' } }];
  }
  const _found = {};
  for (const [role, raw] of _checks) {
    const p = _split(raw);
    const hit = _resolve(p.who) || _fromSaid(p.who);
    if (!hit) {
      const sug = _suggest(p.who);
      return [{ json: { verdict:'REJECTED', reason:'ENGINEER_UNKNOWN', role, given: p.who, suggestions: sug,
        human:'"' + p.who + '" is not on the Hit Productions staff list. '
            + (sug.length ? 'Did you mean ' + sug.join(' or ') + '?' : 'Who is the ' + role + '?') } }];
    }
    _found[role] = { hit, role: p.role };
  }
  // v55: no role given - take the one in Info that matches the department ("Secondary Loc Engineer" -> Loc Engineer).
  const _roleFrom = (hit, want) => {
    const re = want === 'arranger' ? /music arranger/i : ({ 'audio post': /post engineer/i, 'music': /music engineer/i,
      'localization': /loc(?:alization)? engineer/i })[String(REQ.department || '').trim().toLowerCase()];
    if (!re) return '';
    const hitRole = String(hit.info || '').replace(/goes by[^\n]*/i, '').split(/[,.]/).map(s => s.trim()).find(s => re.test(s));
    return hitRole ? ' (' + hitRole.replace(/^secondary\s+/i, '') + ')' : '';
  };
  if (_found.engineer && !_found.engineer.role) _found.engineer.role = _roleFrom(_found.engineer.hit, 'engineer');
  if (_found.engineer) {
    const e = _found.engineer;
    REQ.engineer = e.hit.name + e.role;
