// Decide Preempt - inlined from workflows/drafts/preempt/{decide,branch,logic}.js (offline-tested, 20/20).
const cc = $input.first().json || {};
const REQ = $('When Executed by Another Workflow').first().json || {};
// M-Booth (MBOOTH caller) - GENERALIZED (approach A): any M<n> booth, any RECURRING conflict is a
// standing hold, holder read off the hold's ref: tag. No hard-coded booth list. See mbooth/logic.js.
function isMBooth(r){ return /^M\d+$/i.test(String(r==null?'':r).trim()); }
function parseHoldName(s){ const m=String(s||'').match(/^\s*M\d+\s*-\s*(.+?)\s*$/i); return m?m[1].trim():''; }
function isStandingHold(x){ return !!(x && x.recurring); }
function decideMBooth(cc2, R2){ const room=String((R2&&R2.rooms)||'').trim(); if(!isMBooth(room)) return {action:'none'}; if(!cc2||cc2.reason!=='ROOM_OCCUPIED'||!Array.isArray(cc2.conflicts)||!cc2.conflicts.length) return {action:'none'}; const holds=cc2.conflicts.filter(isStandingHold), nonHolds=cc2.conflicts.filter(function(c){return !isStandingHold(c);}); if(!holds.length) return {action:'none'}; if(nonHolds.length) return {action:'room_taken'}; var holder='',holdName='',holdEventId='',holdTitle=''; for(const h of holds){ const r=parseRef(h.description); if(r){ holder=r; holdName=parseHoldName(h.summary); holdEventId=h.id||''; holdTitle=h.summary||''; break; } } if(!holder) return {action:'unidentified_holder'}; const requester=parseRef(R2.description); if(requester&&requester===holder) return {action:'book_as_holder'}; return {action:'open_mbooth',approver:holder,approverName:holdName,booth:room,holdEventId:holdEventId,holdTitle:holdTitle}; }
const _mb = decideMBooth(cc, REQ);
if(_mb.action==='open_mbooth'){ const mbPayload=JSON.stringify({ summary:REQ.summary, start_iso:REQ.start_iso, end_iso:REQ.end_iso, rooms:_mb.booth, description:REQ.description, session_type:REQ.session_type, client:REQ.client, department:REQ.department, engineer:REQ.engineer, bookingType:REQ.bookingType, all_day:REQ.all_day, reference_data:REQ.reference_data }); return [{ json:{ offer:true, reason:'MBOOTH', open:{ kind:'MBOOTH', requester:parseRef(REQ.description)||'', requesterName:parseBookedBy(REQ.description), approver:_mb.approver, approverName:_mb.approverName, room:_mb.booth, reqStart:REQ.start_iso, reqEnd:REQ.end_iso, incumbentEventId:_mb.holdEventId||'', incumbentTitle:_mb.holdTitle||'', reqType:REQ.session_type, reqPriority:'', incPriority:'', reqPayload:mbPayload, requesterDM:'', approverDM:'' } } }]; }
if(_mb.action==='room_taken'){ return [{ json: Object.assign({}, cc, { offer:false, preemptReason:'MBOOTH_ROOM_TAKEN' }) }]; }

function normType(s){ return String(s==null?'':s).trim().toLowerCase().replace(/\s+/g,' '); }
function rankOf(m,t){ const n=m[normType(t)]; return Number.isFinite(n)?n:undefined; }
function decidePreempt(rq,inc,m,opts){ const au=!!(opts&&opts.authorized); const a=rankOf(m,rq),b=rankOf(m,inc); const r=(a===undefined?0:a);
  if(!au) return {preempt:false,reason:'NOT_AUTHORIZED',rq:r,inc:(b===undefined?null:b)};
  if(b===undefined) return {preempt:false,reason:'INCUMBENT_RANK_UNKNOWN',rq:r,inc:null};
  if(r>b) return {preempt:true,reason:'OUTRANKS',rq:r,inc:b};
  return {preempt:false,reason:(r===b?'EQUAL_RANK':'LOWER_RANK'),rq:r,inc:b}; }
function parseSType(x){ const m=String(x||'').match(/SType:\s*([^\n|]+)/i); return m?m[1].trim():null; }
function parseRef(x){ const m=String(x||'').match(/ref:\s*([A-Z0-9]+)/i); return m?m[1].trim():null; }
function parseBookedBy(x){ const m=String(x||'').match(/Booked by:\s*([^|\n]+)/i); return m?m[1].trim():''; }
function isAuth(a){ return /(dept head|client booking|haist dev)/i.test(String(a||'')); }
function ranksFromRef(rd){ let ref={}; try{ ref=(rd&&typeof rd==='object')?rd:JSON.parse(rd||'{}'); }catch(_){ref={};} const raw=ref.preemptionRanks||{}; const m={}; for(const k in raw){ const n=Number(raw[k]); if(Number.isFinite(n)) m[normType(k)]=n; } return m; }
const eligible = cc && cc.reason==='ROOM_OCCUPIED' && Array.isArray(cc.conflicts) && cc.conflicts.length===1;
if(!eligible) return [{ json: Object.assign({}, cc, { offer:false, preemptReason:'NOT_ELIGIBLE' }) }];
const inc = cc.conflicts[0] || {};
const approver = parseRef(inc.description);
const d = decidePreempt(REQ.session_type, parseSType(inc.description), ranksFromRef(REQ.reference_data), { authorized:isAuth(REQ.authority) });
if(!d.preempt) return [{ json: Object.assign({}, cc, { offer:false, preemptReason:d.reason }) }];
if(!approver) return [{ json: Object.assign({}, cc, { offer:false, preemptReason:'NO_INCUMBENT_BOOKER' }) }];
// PENDING 28 (2026-09-28): booking over your OWN booking is not a preemption - it used to DM you to consent to yourself.
if(approver === (parseRef(REQ.description)||'')) return [{ json: Object.assign({}, cc, { offer:false, preemptReason:'SELF_BOOKING', human:'You already have ' + (inc.room||REQ.rooms) + ' booked then (' + '"' + (inc.summary||'your booking') + '"' + '). Nothing was changed - if you want that booking moved or changed, say so; or pick another room or time.' }) }];
const reqPayload = JSON.stringify({ summary:REQ.summary, start_iso:REQ.start_iso, end_iso:REQ.end_iso, rooms:inc.room||REQ.rooms, description:REQ.description, session_type:REQ.session_type, client:REQ.client, department:REQ.department, engineer:REQ.engineer, bookingType:REQ.bookingType, all_day:REQ.all_day, reference_data:REQ.reference_data });
const open = { requester:parseRef(REQ.description)||'', requesterName:parseBookedBy(REQ.description), approver:approver, approverName:'', room:inc.room||REQ.rooms, reqStart:REQ.start_iso, reqEnd:REQ.end_iso, incumbentEventId:inc.id||'', incumbentTitle:inc.summary||'', reqType:REQ.session_type, reqPriority:d.rq, incPriority:d.inc, reqPayload:reqPayload, requesterDM:'', approverDM:'' };
return [{ json:{ offer:true, reason:'OUTRANKS', open:open } }];

const r = $input.first().json || {};
return [{ json: { status:'PREEMPT_PENDING', request_id: r.request_id || '',
  human: r.message || 'I have asked the current holder of that room for their OK, and will confirm once they reply.' } }];

